//! Go bindings for libghostty-vt, generated by zigo.
const zigo = @import("zigo");
const gostty = @import("gostty");

pub const bindings = zigo.define(.{
    .root = gostty,
    .allocator = .smp_allocator,
    .io = "io",
    .types = .{
        .{ .type = gostty.Terminal, .repr = .@"opaque" },
        .{ .type = gostty.Stream, .repr = .@"opaque", .name = "Stream" },
        .{ .name = "CursorStyle", .type = gostty.CursorStyle, .repr = .enumeration },
        .{ .name = "CursorStyleReq", .type = gostty.CursorStyleReq, .repr = .enumeration },
        .{ .name = "EraseDisplay", .type = gostty.EraseDisplay, .repr = .enumeration },
        // ghostty leaves these two non-exhaustive so a number from a pty never
        // fails `@enumFromInt`; carry that through to Go rather than closing it.
        .{ .name = "EraseLine", .type = gostty.EraseLine, .repr = .enumeration, .exhaustive = false },
        .{ .name = "TabClear", .type = gostty.TabClear, .repr = .enumeration, .exhaustive = false },
        .{ .name = "ProtectedMode", .type = gostty.ProtectedMode, .repr = .enumeration },
    },
    .functions = .{
        .{ .path = "root.unicode.codepointWidth" },
        .{ .path = "root.graphemeWidth", .params = .{"cps"} },

        // Lifecycle. `Terminal.init` returns by value and takes an `Options`
        // that cannot cross the C ABI, so the pair lives outside the type.
        .{ .path = "root.newTerminal", .constructs = "Terminal" },
        .{ .path = "root.freeTerminal", .destroys = "Terminal" },
        .{ .path = "root.freeString", .params = .{"str"} },
        .{ .path = "root.newStream", .constructs = "Stream", .params = .{"continuation_max_bytes"} },
        .{ .path = "root.freeStream", .destroys = "Stream" },
        .{ .path = "root.streamFailed", .name = "failed" },
        .{ .path = "Stream.nextSlice", .name = "feed", .params = .{"input"} },
        .{ .path = "Stream.writeContinuation", .params = .{"writer"} },

        // ghostty's own methods, bound directly.
        .{ .path = "Terminal.printString", .params = .{"str"} },
        .{ .path = "Terminal.plainString", .returns = .caller, .release = "root.freeString" },
        .{ .path = "Terminal.setCursorStyle", .params = .{"value"} },
        .{ .path = "Terminal.setCursorPos", .params = .{ "row_req", "col_req" } },
        .{ .path = "Terminal.carriageReturn" },
        .{ .path = "Terminal.linefeed" },
        .{ .path = "Terminal.backspace" },
        .{ .path = "Terminal.cursorIsAtPrompt" },
        .{ .path = "Terminal.fullReset" },

        // Cursor movement.
        .{ .path = "Terminal.cursorUp", .params = .{"count_req"} },
        .{ .path = "Terminal.cursorDown", .params = .{"count_req"} },
        .{ .path = "Terminal.cursorLeft", .params = .{"count_req"} },
        .{ .path = "Terminal.cursorRight", .params = .{"count_req"} },
        .{ .path = "Terminal.saveCursor" },
        .{ .path = "Terminal.restoreCursor" },
        .{ .path = "Terminal.index" },
        .{ .path = "Terminal.reverseIndex" },

        // Tab stops.
        .{ .path = "Terminal.horizontalTab" },
        .{ .path = "Terminal.horizontalTabBack" },
        .{ .path = "Terminal.tabSet" },
        .{ .path = "Terminal.tabReset" },
        .{ .path = "Terminal.tabClear", .params = .{"cmd"} },

        // Scrolling and margins.
        .{ .path = "Terminal.scrollUp", .params = .{"count"} },
        .{ .path = "Terminal.scrollDown", .params = .{"count"} },
        .{ .path = "Terminal.setTopAndBottomMargin", .params = .{ "top_req", "bottom_req" } },
        .{ .path = "Terminal.setLeftAndRightMargin", .params = .{ "left_req", "right_req" } },
        .{ .path = "Terminal.setScrollbackMaxBytes", .params = .{"max"} },
        .{ .path = "Terminal.setScrollbackMaxLines", .params = .{"max"} },

        // Editing.
        .{ .path = "Terminal.insertLines", .params = .{"count"} },
        .{ .path = "Terminal.deleteLines", .params = .{"count"} },
        .{ .path = "Terminal.insertBlanks", .params = .{"count"} },
        .{ .path = "Terminal.deleteChars", .params = .{"count_req"} },
        .{ .path = "Terminal.eraseChars", .params = .{"count_req"} },
        .{ .path = "Terminal.eraseLine", .params = .{ "mode", "protected_req" } },
        .{ .path = "Terminal.eraseDisplay", .params = .{ "mode", "protected_req" } },
        .{ .path = "Terminal.decaln" },

        // Printing.
        .{ .path = "Terminal.print", .params = .{"c"} },
        .{ .path = "Terminal.printRepeat", .params = .{"count_req"} },
        .{ .path = "Terminal.plainStringUnwrapped", .returns = .caller, .release = "root.freeString" },

        // Metadata the terminal tracks for the shell.
        .{ .path = "Terminal.setPwd", .params = .{"pwd"} },
        .{ .path = "Terminal.getPwd" },
        .{ .path = "Terminal.getTitle" },
        .{ .path = "Terminal.setTitle", .params = .{"t"} },
        .{ .path = "Terminal.setProtectedMode", .params = .{"mode"} },
        .{ .path = "Terminal.compressionActivity" },
        .{ .path = "root.resize", .params = .{ "width", "height" } },

        // Field accessors: zigo binds functions, not fields.
        .{ .path = "root.cols" },
        .{ .path = "root.rows" },
        .{ .path = "root.cursorX" },
        .{ .path = "root.cursorY" },
        .{ .path = "root.cursorStyle" },
    },
});
